from __future__ import annotations

import json
import sys
from pathlib import Path


TASK_DIR = Path(__file__).resolve().parent
SOURCE_DIR = TASK_DIR / "source"
sys.path.insert(0, str(SOURCE_DIR))


def _write_report(report: dict) -> int:
    out_dir = TASK_DIR / "outputs"
    out_dir.mkdir(exist_ok=True)
    (out_dir / "reproduction.json").write_text(
        json.dumps(report, indent=2, sort_keys=True), encoding="utf-8"
    )
    print(json.dumps(report, indent=2, sort_keys=True))
    return 0 if report["status"] != "runner_failure" else 1


def main() -> int:
    try:
        from automol import graph

        from workflow.case import CASE_GRAPH, CONTROL_GRAPH
        from workflow.observe import transition_state_observation
    except Exception:
        return _write_report(
            {
                "status": "runner_failure",
                "scientific_observation": {},
                "runner_error": "task source could not be imported",
            }
        )

    try:
        observation = transition_state_observation(graph, CASE_GRAPH, CONTROL_GRAPH)
        return _write_report(
            {
                "status": "workflow_completed",
                "scientific_observation": observation,
                "runner_error": None,
            }
        )
    except Exception:
        return _write_report(
            {
                "status": "runner_failure",
                "scientific_observation": {},
                "runner_error": "scientific graph fixture could not be evaluated",
            }
        )


